    "settings.diagnostics.providerRequestTrace.actionFailed": "No se completó",
    "settings.diagnostics.providerRequestTrace.description": "Cuando está activado, la solicitud final enviada y cada reintento físico de una misma solicitud lógica al Provider se registran en un grupo, junto con los metadatos de la respuesta, los bytes de respuesta sin procesar antes del parser, los límites de chunks o tramas WebSocket y el resultado fallido. El directorio temp/provider-api-trace de la sesión propietaria rota entre cuatro espacios de solicitudes lógicas; cada intento conserva hasta 64 MiB de datos de respuesta sin procesar, incluidos los bytes recibidos antes de un fallo o una cancelación manual. Las tareas Batch de embeddings de VCE también conservan los archivos exactos de solicitud y los archivos completos output/error del Provider en el árbol temp/vce del directorio de datos de la aplicación, separados por proyecto y tarea, sin rotación automática. Los archivos pueden contener prompts, código fuente, argumentos y resultados de herramientas y salida del Provider; actívalo solo mientras diagnosticas un problema.",
